// Un item limpio por mensaje de WhatsApp. Las notificaciones de estado (enviado, entregado, leído) se descartan aquí.
const out = [];
$input.all().forEach((item, index) => {
  const raw = item.json;
  const v = raw.messages ? raw : (raw.entry?.[0]?.changes?.[0]?.value ?? raw);
  const msg = v.messages?.[0];
  if (!msg) return;

  const contacto = v.contacts?.[0] ?? {};
  let tipo = msg.type;
  let texto = '';
  let eleccion = null;

  if (msg.type === 'text') texto = msg.text?.body ?? '';
  else if (msg.type === 'interactive') {
    const r = msg.interactive?.button_reply ?? msg.interactive?.list_reply ?? {};
    texto = r.title ?? '';
    // los botones de horario llevan la reserva en su id: {"i": inicio, "n": nombre, "s": servicio}
    try {
      const p = JSON.parse(r.id);
      if (p && p.i) { eleccion = p; tipo = 'eleccion'; }
    } catch (e) {}
  } else if (msg.type === 'button') {
    // respuesta rápida a la plantilla: la única con botones es el recordatorio de la reserva
    texto = `${msg.button?.text ?? ''} (respuesta al recordatorio de su reserva de mañana)`;
  } else if (msg.type !== 'audio') texto = `[El cliente envió un mensaje de tipo "${msg.type}" que no se puede leer]`;

  out.push({
    json: {
      tipo,
      texto,
      telefono: msg.from,
      nombre: eleccion?.n || contacto.profile?.name || '',
      audioId: msg.audio?.id ?? null,
      mensajeId: msg.id,
      phoneNumberId: v.metadata?.phone_number_id,
      // solo si tocó un botón de horario
      inicio: eleccion?.i ?? null,
      servicio: eleccion?.s ?? '',
    },
    pairedItem: { item: index },
  });
});
return out;

// Whisper detects the format from the file extension, and WhatsApp's download has none.
// Voice notes arrive as OGG; attached audio files can be MP3, M4A, WAV or WEBM.
const extensiones = {
  'audio/ogg': 'ogg', 'audio/opus': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3',
  'audio/mp4': 'm4a', 'audio/m4a': 'm4a', 'audio/x-m4a': 'm4a', 'audio/aac': 'm4a',
  'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/webm': 'webm',
};
for (const item of $input.all()) {
  const audio = item.binary?.data;
  if (!audio) continue;
  const tipo = String(audio.mimeType ?? '').split(';')[0].trim().toLowerCase();
  const ext = extensiones[tipo] ?? 'ogg';
  audio.fileName = `nota-de-voz.${ext}`;
  audio.fileExtension = ext;
}
return $input.all();

