// Convierte la respuesta del agente en lo que necesita WhatsApp, más el contexto de la conversación.
const ctx = $('Lee el mensaje').item.json;
const o = $json.output ?? {};
// Si el agente falló (API caída, sin créditos...): responde con cortesía y avisa al barbero.
const fallo = !$json.output;
const corta = (s, n) => String(s ?? '').replace(/\s+/g, ' ').trim().slice(0, n);

let original = ctx.texto;
try { original = $('Transcribe audio').item.json.text || original; } catch (e) {}

const nombre = corta(o.nombre_cliente || ctx.nombre, 40);
const servicio = corta(o.servicio, 40);

// Botones de respuesta de WhatsApp: máx. 3, títulos únicos de hasta 20 caracteres, ids de hasta 256
const vistos = new Set();
const botones = (Array.isArray(o.botones) ? o.botones : [])
  .filter((b) => b && b.inicio && b.titulo && !vistos.has(corta(b.titulo, 20)) && vistos.add(corta(b.titulo, 20)))
  .slice(0, 3)
  .map((b) => ({
    type: 'reply',
    reply: { id: JSON.stringify({ i: b.inicio, n: nombre, s: servicio }).slice(0, 256), title: corta(b.titulo, 20) },
  }));

let accion = fallo ? 'derivar' : o.accion || 'responder';
if (accion === 'ofrecer_horarios' && botones.length === 0) accion = 'responder';
if (accion === 'reservar' && !DateTime.fromISO(String(o.cita_inicio ?? '')).isValid) accion = 'responder';

return {
  json: {
    accion,
    respuesta: o.respuesta || 'Gracias por escribir 🙏 En cuanto pueda, el barbero te responde por aquí.',
    botones,
    nombre,
    servicio,
    inicio: o.cita_inicio ?? null,
    telefono: ctx.telefono,
    phoneNumberId: ctx.phoneNumberId,
    mensajeOriginal: corta(original, 180),
  },
};

// Valida la hora pedida (futura, dentro del horario, alineada a la duración) y prepara los datos de la reserva.
const cfg = $('Datos de la barbería').first().json;
const j = $json;
const dur = Number(cfg.duracionMinutos) || 30;
const ini = DateTime.fromISO(String(j.inicio ?? ''), { setZone: true });
const local = ini.isValid ? ini.setZone(cfg.zonaHoraria) : ini;

let valida = false;
if (ini.isValid && ini > DateTime.now()) {
  let semana = {};
  try { semana = JSON.parse(cfg.horarioSemana); } catch (e) {}
  const dia = semana[String(local.weekday)];
  if (Array.isArray(dia)) {
    const aMin = (h) => { const [a, b] = String(h).split(':').map(Number); return a * 60 + b; };
    const m = local.hour * 60 + local.minute;
    valida = m >= aMin(dia[0]) && m + dur <= aMin(dia[1]) && (m - aMin(dia[0])) % dur === 0;
  }
}
const fin = ini.isValid ? ini.plus({ minutes: dur }) : ini;
return {
  json: {
    valida,
    telefono: j.telefono,
    phoneNumberId: j.phoneNumberId,
    nombre: j.nombre || 'Cliente',
    servicio: j.servicio || 'Corte',
    inicio: ini.isValid ? ini.toISO() : null,
    inicioUtc: ini.isValid ? ini.toUTC().toISO({ suppressMilliseconds: true }) : null,
    finUtc: fin.isValid ? fin.toUTC().toISO({ suppressMilliseconds: true }) : null,
    inicioLegible: local.isValid ? local.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm") : '',
    // El id del documento ES la hora (UTC): si ya existe, Firestore rechaza la reserva con 409. Así nunca hay dos reservas en la misma hora.
    docId: ini.isValid ? ini.toUTC().toFormat("yyyyMMdd'T'HHmm") : null,
  },
};

// Un recordatorio por reserva de mañana. runQuery devuelve un item por documento (o uno vacío si no hay ninguno).
const cfg = $('Datos de la barbería (mañana)').first().json;
const out = [];
for (const { json: r } of $input.all()) {
  const f = r.document?.fields;
  if (!f || f.estado?.stringValue === 'cancelada') continue;
  const tel = String(f.telefono?.stringValue ?? '').replace(/\D/g, '');
  if (tel.length < 8 || !f.inicio?.timestampValue) continue;
  const hora = DateTime.fromISO(f.inicio.timestampValue, { setZone: true }).setZone(cfg.zonaHoraria).toFormat('HH:mm');
  out.push({ json: { telefono: tel, nombre: f.nombre?.stringValue || 'Hola', hora } });
}
return out;
